  const edgesG = document.getElementById('edges');
  const nodesG = document.getElementById('nodes');
  const bfG = document.getElementById('bfLabels');
  const stepDisplay = document.getElementById('stepDisplay');
  const descDisplay = document.getElementById('descDisplay');
  const prevBtn = document.getElementById('prevBtn');
  const nextBtn = document.getElementById('nextBtn');
  const resetBtn = document.getElementById('resetBtn');

  const descriptions = [
    '仅根节点 3',
    '插入 2，节点 3 平衡因子 = 1',
    '插入 1，节点 3 平衡因子 = 2（失衡）',
    '右旋后，根为 2，左 1 右 3，所有平衡因子 = 0'
  ];

  // 树数据：每个步骤的节点列表和边列表
  const treeStates = [
    // step 0: 只有 3
    { nodes: [{ id: 3, x: 200, y: 60, bf: 0, highlight: false }], edges: [] },
    // step 1: 3 左 2
    { nodes: [
        { id: 3, x: 200, y: 60, bf: 1, highlight: false },
        { id: 2, x: 120, y: 140, bf: 0, highlight: false }
      ], edges: [{ from: 3, to: 2, dir: 'left' }] },
    // step 2: 3 左 2 左 1
    { nodes: [
        { id: 3, x: 200, y: 60, bf: 2, highlight: true },
        { id: 2, x: 120, y: 140, bf: 1, highlight: false },
        { id: 1, x: 60, y: 220, bf: 0, highlight: false }
      ], edges: [{ from: 3, to: 2, dir: 'left' }, { from: 2, to: 1, dir: 'left' }] },
    // step 3: 右旋后 2 为根，左 1 右 3
    { nodes: [
        { id: 2, x: 200, y: 60, bf: 0, highlight: false },
        { id: 1, x: 100, y: 140, bf: 0, highlight: false },
        { id: 3, x: 300, y: 140, bf: 0, highlight: false }
      ], edges: [{ from: 2, to: 1, dir: 'left' }, { from: 2, to: 3, dir: 'right' }] }
  ];

  function getThemeColors() {
    const root = document.documentElement;
    const style = getComputedStyle(root);
    return {
      ink: style.getPropertyValue('--ink').trim(),
      text2: style.getPropertyValue('--text2').trim(),
      accent: style.getPropertyValue('--accent').trim(),
      line: style.getPropertyValue('--line').trim() || 'rgba(90,78,128,.25)',
      bg: style.getPropertyValue('--bg').trim(),
      bg2: style.getPropertyValue('--bg2').trim(),
      card: style.getPropertyValue('--card').trim()
    };
  }

  function drawTree(step) {
    const colors = getThemeColors();
    const state = treeStates[step];
    const nodeRadius = 24;

    // 清空
    edgesG.innerHTML = '';
    nodesG.innerHTML = '';
    bfG.innerHTML = '';

    // 画边
    state.edges.forEach(e => {
      const fromNode = state.nodes.find(n => n.id === e.from);
      const toNode = state.nodes.find(n => n.id === e.to);
      if (!fromNode || !toNode) return;
      const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      line.setAttribute('x1', fromNode.x);
      line.setAttribute('y1', fromNode.y + nodeRadius);
      line.setAttribute('x2', toNode.x);
      line.setAttribute('y2', toNode.y - nodeRadius);
      line.setAttribute('stroke', colors.line);
      line.setAttribute('stroke-width', '2');
      line.setAttribute('marker-end', 'url(#arrow)');
      edgesG.appendChild(line);
    });

    // 画节点
    state.nodes.forEach(n => {
      const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
      const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      circle.setAttribute('cx', n.x);
      circle.setAttribute('cy', n.y);
      circle.setAttribute('r', nodeRadius);
      circle.setAttribute('fill', colors.card);
      circle.setAttribute('stroke', n.highlight ? 'var(--accent)' : colors.line);
      circle.setAttribute('stroke-width', n.highlight ? '3' : '2');
      if (n.highlight) {
        circle.classList.add('pulse');
        circle.setAttribute('stroke', 'var(--accent)');
      }
      g.appendChild(circle);

      const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      text.setAttribute('x', n.x);
      text.setAttribute('y', n.y + 5);
      text.setAttribute('text-anchor', 'middle');
      text.setAttribute('font-size', '16');
      text.setAttribute('font-weight', '600');
      text.setAttribute('fill', colors.ink);
      text.textContent = n.id;
      g.appendChild(text);
      nodesG.appendChild(g);

      // 平衡因子标签
      const bfText = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      bfText.setAttribute('x', n.x + nodeRadius + 10);
      bfText.setAttribute('y', n.y - 8);
      bfText.setAttribute('font-size', '13');
      bfText.setAttribute('fill', n.highlight ? 'var(--accent)' : colors.text2);
      bfText.setAttribute('font-weight', n.highlight ? '700' : '400');
      bfText.textContent = 'BF=' + n.bf;
      bfG.appendChild(bfText);
    });
  }

  function update() {
    const s = stepModel.step;
    stepDisplay.textContent = s;
    descDisplay.textContent = descriptions[s];
    prevBtn.disabled = s === 0;
    nextBtn.disabled = s === maxStep;
    drawTree(s);
  }

  function next() {
    if (stepModel.step < maxStep) {
      stepModel.step++;
      update();
    }
  }

  function prev() {
    if (stepModel.step > 0) {
      stepModel.step--;
      update();
    }
  }

  function reset() {
    stepModel.step = 0;
    update();
  }

  nextBtn.addEventListener('click', next);
  prevBtn.addEventListener('click', prev);
  resetBtn.addEventListener('click', reset);

  // 验证
  (function verify() {
    console.assert(treeStates[0].nodes.length === 1 && treeStates[0].nodes[0].id === 3, 'step0: 仅根节点3');
    console.assert(treeStates[1].nodes.length === 2 && treeStates[1].nodes[1].id === 2, 'step1: 插入2');
    console.assert(treeStates[2].nodes.length === 3 && treeStates[2].nodes[0].bf === 2, 'step2: 节点3 BF=2');
    console.assert(treeStates[3].nodes[0].id === 2 && treeStates[3].nodes[0].bf === 0, 'step3: 右旋后根为2 BF=0');
    console.assert(treeStates[3].nodes[2].id === 3 && treeStates[3].nodes[2].bf === 0, 'step3: 右旋后节点3 BF=0');
  })();

  // 首帧
  update();
})();
</script>

